oracle.script:
cat > settings.py <<'EOF'
import json, os

def load(path):
    out = {}
    try:
        for ln in open(path):
            ln = ln.strip()
            if ln and not ln.startswith('#') and '=' in ln:
                k, v = ln.split('=', 1)
                out[k.strip()] = v.strip()
    except FileNotFoundError:
        pass
    return out

cfg = {**load('defaults.env'), **load('.env')}
for k in ('PORT', 'HOST', 'DEBUG'):
    if k in os.environ:
        cfg[k] = os.environ[k]
res = {'PORT': int(cfg['PORT']), 'HOST': cfg['HOST'], 'DEBUG': cfg['DEBUG'].lower() == 'true'}
json.dump(res, open('resolved.json','w'))
EOF
python3 settings.py
